import * as T from './three.module.js';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import {OrbitControls} from './vendor/OrbitControls.js';
import {TransformControls} from './vendor/TransformControls.js';
import {readGLB,writeRigGLB} from './rig-glb.mjs';
const $=id=>document.getElementById(id),viewport=$('viewport'),scene=new T.Scene();scene.background=new T.Color(0x111923);
const camera=new T.PerspectiveCamera(40,1,.001,1000),renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));viewport.append(renderer.domElement);renderer.outputColorSpace=T.SRGBColorSpace;scene.add(new T.HemisphereLight(0xdaeaff,0x58525b,2));const light=new T.DirectionalLight(0xffebd2,3);light.position.set(2,3,4);scene.add(light);
const orbit=new OrbitControls(camera,renderer.domElement);orbit.enableDamping=true;const gizmo=new TransformControls(camera,renderer.domElement);gizmo.setMode('translate');gizmo.setSpace('world');gizmo.setSize(.8);scene.add(gizmo.getHelper());const proxy=new T.Object3D();scene.add(proxy);
let root,original,filename='wolf',nodes=new Map(),bones=[],selected=null,baseline=[],worldBefore=new Map(),skeletons=[],undo=[],redo=[],markers=[],lines,ghost,grid,bounds,size=1,busy=false,dragSnapshot,childWorld,loading=0,poseBase=null,loadError=false;
const pointGeo=new T.SphereGeometry(1,10,8),green=new T.MeshBasicMaterial({color:0xb9ee9e,depthTest:false}),yellow=new T.MeshBasicMaterial({color:0xffcf66,depthTest:false});
function status(text){$('status').textContent=text;}
function snapshot(){return bones.map(b=>({p:b.position.toArray(),q:b.quaternion.toArray(),s:b.scale.toArray()}));}
function applySnapshot(s){bones.forEach((b,i)=>{b.position.fromArray(s[i].p);b.quaternion.fromArray(s[i].q);b.scale.fromArray(s[i].s);b.updateMatrix();});refreshBind();syncSelection();}
function updateHistory(){ $('undo').disabled=!undo.length;$('redo').disabled=!redo.length;}
function remember(s){undo.push(s);if(undo.length>80)undo.shift();redo=[];updateHistory();}
function clearPose(){if(poseBase&&selected){selected.quaternion.copy(poseBase);selected.updateMatrix();root.updateMatrixWorld(true);}poseBase=null;$('pose').value=0;$('angle').textContent='0°';}
function refreshBind(){if(!root)return;root.updateMatrixWorld(true);for(const entry of skeletons){entry.skeleton.bones.forEach((b,i)=>entry.skeleton.boneInverses[i].copy(b.matrixWorld).invert().multiply(entry.world[i]).multiply(entry.inverses[i]));entry.skeleton.update();}root.traverse(o=>{if(o.isSkinnedMesh){o.computeBoundingBox();o.computeBoundingSphere();}});updateLines();}
function positions(old=false){const out=[];for(const b of bones){if(!b.parent?.isBone)continue;const a=old?worldBefore.get(nodesIndex(b)):b.matrixWorld,c=old?worldBefore.get(nodesIndex(b.parent)):b.parent.matrixWorld;if(a&&c)out.push(...new T.Vector3().setFromMatrixPosition(a).toArray(),...new T.Vector3().setFromMatrixPosition(c).toArray());}return out;}
function nodesIndex(o){return o.userData.rigNodeIndex;}
function updateLines(){if(!root)return;root.updateMatrixWorld(true);markers.forEach((m,i)=>m.position.setFromMatrixPosition(bones[i].matrixWorld));if(lines){lines.geometry.dispose();lines.geometry=new T.BufferGeometry().setAttribute('position',new T.Float32BufferAttribute(positions(),3));}}
function list(){const query=$('search').value.toLowerCase();$('bones').replaceChildren();bones.forEach((b,i)=>{if(!b.name.toLowerCase().includes(query))return;const button=document.createElement('button');button.className='bone'+(b===selected?' selected':'');button.textContent=b.name.replace('tripo::','');button.dataset.index=i;const desc=document.createElement('small');desc.textContent=b.parent?.isBone?'연결: '+b.parent.name.replace('tripo::',''):'기준 관절';button.append(desc);button.onclick=()=>select(b);$('bones').append(button);});}
function select(b){clearPose();selected=b;$('edit').disabled=false;$('name').textContent=b.name;$('parent').textContent='부모: '+(b.parent?.name||'없음');markers.forEach((m,i)=>m.material=bones[i]===b?yellow:green);syncSelection();list();}
function syncSelection(){if(!selected)return;root.updateMatrixWorld(true);const p=selected.getWorldPosition(new T.Vector3());proxy.position.copy(p);gizmo.attach(proxy);for(const [i,key]of ['x','y','z'].entries())$(key).value=p.getComponent(i).toFixed(5);}
function captureChildren(){root.updateMatrixWorld(true);return selected.children.filter(c=>c.isBone).map(c=>[c,c.matrixWorld.clone()]);}
function moveSelected(world,children){selected.position.copy(selected.parent.worldToLocal(world.clone()));selected.updateMatrix();root.updateMatrixWorld(true);if(!$('children').checked)for(const [c,m]of children){const local=selected.matrixWorld.clone().invert().multiply(m);local.decompose(c.position,c.quaternion,c.scale);c.updateMatrix();}refreshBind();syncSelection();status('관절 위치를 변경했습니다. 회전 미리보기로 변형을 확인하세요.');}
gizmo.addEventListener('dragging-changed',e=>{orbit.enabled=!e.value;});gizmo.addEventListener('mouseDown',()=>{clearPose();dragSnapshot=snapshot();childWorld=captureChildren();});gizmo.addEventListener('objectChange',()=>{if(!selected||busy)return;busy=true;moveSelected(proxy.position,childWorld||captureChildren());busy=false;});gizmo.addEventListener('mouseUp',()=>{if(dragSnapshot&&JSON.stringify(dragSnapshot)!==JSON.stringify(snapshot()))remember(dragSnapshot);dragSnapshot=null;});
for(const key of ['x','y','z'])$(key).addEventListener('change',()=>{if(!selected)return;clearPose();const p=new T.Vector3(...['x','y','z'].map(k=>Number($(k).value)));if(!p.toArray().every(Number.isFinite)){syncSelection();return;}const before=snapshot(),children=captureChildren();moveSelected(p,children);remember(before);});
$('pose').oninput=()=>{if(!selected)return;if(!poseBase)poseBase=selected.quaternion.clone();selected.quaternion.copy(poseBase).multiply(new T.Quaternion().setFromAxisAngle(new T.Vector3(...({x:[1,0,0],y:[0,1,0],z:[0,0,1]}[$('axis').value])),Number($('pose').value)*Math.PI/180));selected.updateMatrix();root.updateMatrixWorld(true);updateLines();gizmo.detach();$('angle').textContent=$('pose').value+'°';status('회전 미리보기 중입니다. 이 회전은 저장하지 않습니다.');};$('clearPose').onclick=()=>{clearPose();updateLines();syncSelection();};$('axis').onchange=()=>{$('clearPose').click();};
$('undo').onclick=()=>{if(!undo.length)return;clearPose();redo.push(snapshot());applySnapshot(undo.pop());updateHistory();status('이전 위치로 되돌렸습니다.');};$('redo').onclick=()=>{if(!redo.length)return;clearPose();undo.push(snapshot());applySnapshot(redo.pop());updateHistory();};
$('resetAll').onclick=()=>{if(!root)return;clearPose();remember(snapshot());applySnapshot(baseline);status('모든 관절을 원래 위치로 되돌렸습니다.');};$('resetBone').onclick=()=>{if(!selected)return;clearPose();const before=snapshot();moveSelected(new T.Vector3().setFromMatrixPosition(worldBefore.get(nodesIndex(selected))),captureChildren());remember(before);};
$('search').oninput=list;$('showBones').onchange=()=>{markers.forEach(m=>m.visible=$('showBones').checked);if(lines)lines.visible=$('showBones').checked;};$('ghost').onchange=()=>{if(ghost)ghost.visible=$('ghost').checked;};$('transparent').onchange=()=>{root?.traverse(o=>{if(o.isMesh)for(const m of(Array.isArray(o.material)?o.material:[o.material])){m.transparent=$('transparent').checked||m.userData.origTransparent;m.opacity=$('transparent').checked?.25:m.userData.origOpacity;m.depthWrite=!$('transparent').checked;m.needsUpdate=true;}});};
function fit(view='side'){if(!root)return;const center=bounds.getCenter(new T.Vector3()),distance=size*1.65,dir={side:[1,.12,0],front:[0,.12,1],back:[0,.12,-1],top:[0,1,.0001]}[view];camera.position.copy(center).add(new T.Vector3(...dir).normalize().multiplyScalar(distance));camera.near=size/1000;camera.far=size*100;camera.updateProjectionMatrix();orbit.target.copy(center);orbit.update();}document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>fit(b.dataset.view));$('fit').onclick=()=>fit();
let pointerStart;renderer.domElement.addEventListener('pointerdown',e=>pointerStart=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',e=>{if(gizmo.axis||!pointerStart||Math.hypot(e.clientX-pointerStart[0],e.clientY-pointerStart[1])>4)return;const r=renderer.domElement.getBoundingClientRect(),ray=new T.Raycaster();ray.setFromCamera(new T.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hit=ray.intersectObjects(markers.filter(m=>m.visible))[0];if(hit)select(bones[hit.object.userData.index]);});
function cleanup(){gizmo.detach();selected=null;poseBase=null;for(const m of markers)scene.remove(m);markers=[];for(const x of [root,lines,ghost,grid])if(x){scene.remove(x);x.traverse(o=>{if(o.geometry&&o.geometry!==pointGeo)o.geometry.dispose();if(o.material)for(const m of(Array.isArray(o.material)?o.material:[o.material])){if(m===green||m===yellow)continue;for(const v of Object.values(m))if(v?.isTexture)v.dispose();m.dispose();}});}root=null;}
async function load(buffer,name){const id=++loading;$('download').disabled=true;status('모델과 관절을 불러오는 중입니다.');try{const source=readGLB(buffer);if(source.json.buffers.some(b=>b.uri)||source.json.images?.some(i=>i.uri&&!i.uri.startsWith('data:')))throw Error('외부 파일이 없는 단일 GLB로 내보내서 다시 열어 주세요.');const gltf=await new GLTFLoader().parseAsync(buffer,'');if(id!==loading)return;cleanup();original=source;filename=name.replace(/\.glb$/i,'');root=gltf.scene;scene.add(root);root.updateMatrixWorld(true);nodes=new Map();bones=[];worldBefore=new Map();root.traverse(o=>{const i=gltf.parser.associations.get(o)?.nodes;if(i!==undefined){nodes.set(i,o);o.userData.rigNodeIndex=i;worldBefore.set(i,o.matrixWorld.clone());}if(o.isBone)bones.push(o);if(o.isMesh)for(const m of(Array.isArray(o.material)?o.material:[o.material])){m.userData.origOpacity=m.opacity;m.userData.origTransparent=m.transparent;}});if(!bones.length)throw Error('관절을 찾지 못했습니다. 리깅된 GLB를 선택해 주세요.');skeletons=[];const seen=new Set();root.traverse(o=>{if(o.isSkinnedMesh&&!seen.has(o.skeleton)){seen.add(o.skeleton);skeletons.push({skeleton:o.skeleton,inverses:o.skeleton.boneInverses.map(m=>m.clone()),world:o.skeleton.bones.map(b=>b.matrixWorld.clone())});}});bounds=new T.Box3().setFromObject(root);size=bounds.getSize(new T.Vector3()).length();grid=new T.GridHelper(size*2,20,0x40566b,0x253747);grid.position.y=bounds.min.y;scene.add(grid);bones.forEach((b,i)=>{const m=new T.Mesh(pointGeo,green);m.scale.setScalar(size*.006);m.renderOrder=20;m.userData.index=i;scene.add(m);markers.push(m);});lines=new T.LineSegments(new T.BufferGeometry(),new T.LineBasicMaterial({color:0xb9ee9e,depthTest:false,transparent:true,opacity:.9}));lines.renderOrder=19;scene.add(lines);ghost=new T.LineSegments(new T.BufferGeometry().setAttribute('position',new T.Float32BufferAttribute(positions(true),3)),new T.LineBasicMaterial({color:0x6585a7,transparent:true,opacity:.45,depthTest:false}));ghost.renderOrder=18;scene.add(ghost);baseline=snapshot();undo=[];redo=[];updateHistory();updateLines();list();$('count').textContent=bones.length;$('download').disabled=false;$('edit').disabled=true;$('name').textContent='관절을 선택하세요';$('parent').textContent='';$('showBones').onchange();$('ghost').onchange();$('transparent').onchange();fit();loadError=false;status(`${name} · 관절 ${bones.length}개 · 파일은 브라우저 안에서 편집합니다.`);}catch(e){loadError=true;status('불러오지 못했습니다. '+e.message);if(root)$('download').disabled=false;}}
$('file').onchange=async e=>{const file=e.target.files[0];if(file)await load(await file.arrayBuffer(),file.name);e.target.value='';};
function exportBuffer(){clearPose();updateLines();syncSelection();root.updateMatrixWorld(true);const local=new Map(),world=new Map();for(const [i,o]of nodes){o.updateMatrix();local.set(i,o.matrix.clone());world.set(i,o.matrixWorld.clone());}return writeRigGLB(original,local,worldBefore,world);}
$('download').onclick=()=>{try{const buffer=exportBuffer(),url=URL.createObjectURL(new Blob([buffer],{type:'model/gltf-binary'})),a=document.createElement('a');a.href=url;a.download=filename+'-rig-edited.glb';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);status('수정한 기본 자세를 저장했습니다. 기존 애니메이션은 제외했습니다.');}catch(e){status('저장하지 못했습니다. '+e.message);}};
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click();}});
new ResizeObserver(()=>{const w=viewport.clientWidth,h=viewport.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();}).observe(viewport);
function frame(){requestAnimationFrame(frame);orbit.update();renderer.render(scene,camera);}frame();
window.rigEditorDebug={screen:(i,dy=0)=>{const p=bones[i].getWorldPosition(new T.Vector3());p.y+=dy;p.project(camera);const r=renderer.domElement.getBoundingClientRect();return {x:r.left+(p.x+1)*r.width/2,y:r.top+(1-p.y)*r.height/2};},state:()=>({ready:!!root&&!loadError,bones:bones.length,selected:selected?.name,undo:undo.length,positions:bones.map(b=>({name:b.name,p:b.getWorldPosition(new T.Vector3()).toArray()}))}),select:i=>select(bones[i]),exportBuffer,load,vertices:()=>{root.updateMatrixWorld(true);const result=[];root.traverse(o=>{if(o.isSkinnedMesh){o.skeleton.update();for(let i=0;i<o.geometry.attributes.position.count;i+=97)result.push(...o.getVertexPosition(i,new T.Vector3()).applyMatrix4(o.matrixWorld).toArray());}});return result;}};
fetch('assets/rig-editor/wolf-original.glb').then(r=>{if(!r.ok)throw Error('기본 늑대 파일이 없습니다. GLB 열기로 파일을 선택해 주세요.');return r.arrayBuffer();}).then(b=>load(b,'wolf-original.glb')).catch(e=>status(e.message));
